@Composable fun DatePickerInput( modifier: Modifier = Modifier, selectedDate: String, onDateSelected: (String) -> Unit, placeholder: String = "Select date" ) { val context = LocalContext.current val calendar = Calendar.getInstance()
val datePickerDialog = DatePickerDialog(
context, { _, year, month, dayOfMonth -> onDateSelected("$dayOfMonth - ${month + 1} - $year") }, calendar.get(Calendar.YEAR), calendar.get(Calendar.MONTH), calendar.get(Calendar.DAY_OF_MONTH) ).apply { datePicker.maxDate = System.currentTimeMillis() }
Row( modifier = modifier .fillMaxWidth() .clip(RoundedCornerShape(12.dp)) .background(Color.LightGray.copy(alpha = 0.2f)) .clickable { datePickerDialog.show() } .padding(horizontal = 16.dp, vertical = 14.dp), verticalAlignment = Alignment.CenterVertically ) { Text( text = if (selectedDate.isBlank()) placeholder else selectedDate, modifier = Modifier.weight(1f), color = if (selectedDate.isBlank()) Color.Gray else Color.Black )
Icon( imageVector = Icons.Default.DateRange, contentDescription = "Pick date" ) } }

