                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.surface
                )
            )
        },
        containerColor = MaterialTheme.colorScheme.background
    ) { paddingValues ->

        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .padding(horizontal = 20.dp, vertical = 16.dp)
                .background(MaterialTheme.colorScheme.background)
        ) {
            Text(
                text = "Case No. ${caseItem?.caseNumber}",
                fontSize = 20.sp,
                fontWeight = FontWeight.SemiBold,
                color = MaterialTheme.colorScheme.onSurface
            )

            Text(
                text = "${caseItem?.incidentType}",
                fontSize = 17.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )

            Spacer(modifier = Modifier.height(16.dp))

            LazyColumn(
                modifier = Modifier.fillMaxSize()
            ) {
                itemsIndexed(trackingSteps) { index, step ->
                    val isCompleted = index == 0
                    ProgressTimelineRow(
                        title = step.title,
                        timestamp = step.timestamp,
                        isCompleted = isCompleted,
                        drawLine = index < trackingSteps.lastIndex,
                        isActiveLine = isCompleted
                    )
                }

                item {
                    Spacer(modifier = Modifier.height(14.dp))
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = 28.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Box(
                            modifier = Modifier
                                .size(60.dp)
                                .background(InactiveGray, CircleShape),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Default.Check,
                                contentDescription = null,
                                tint = MaterialTheme.colorScheme.onSurface
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun ProgressTimelineRow(
    title: String,
    timestamp: String?,
    isCompleted: Boolean,
    drawLine: Boolean,
    isActiveLine: Boolean
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(bottom = 8.dp),
        verticalAlignment = Alignment.Top
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            modifier = Modifier.padding(top = 2.dp)
        ) {
            Box(
                modifier = Modifier
                    .size(20.dp)
                    .background(if (isCompleted) ActivePurple else InactiveGray, CircleShape),
                contentAlignment = Alignment.Center
            ) {
                if (isCompleted) {
                    Icon(
                        imageVector = Icons.Default.Check,
                        contentDescription = null,
                        tint = Color.White,
                        modifier = Modifier.size(16.dp)
                    )
                }
            }

            if (drawLine) {
                Canvas(
                    modifier = Modifier
                        .height(60.dp)
                        .padding(top = 2.dp)
                        .size(2.dp, 68.dp)
                ) {
                    drawLine(
                        color = if (isActiveLine) ActivePurple else InactiveGray,
                        start = Offset(size.width / 2f, 0f),
                        end = Offset(size.width / 2f, size.height),
                        strokeWidth = 6f
                    )
                }
            }
        }

        Spacer(modifier = Modifier.size(14.dp))

        Column(modifier = Modifier.padding(top = 0.dp)) {
            Text(
                text = title,
                fontSize = 14.sp,
                color = if (isCompleted) ActivePurple else MaterialTheme.colorScheme.onSurface,
                fontWeight = if (isCompleted) FontWeight.Medium else FontWeight.Normal
            )
            if (!timestamp.isNullOrBlank()) {
                Text(
                    text = timestamp,
                    fontSize = 12.sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    modifier = Modifier.padding(top = 2.dp)
                )
            }
        }
    }
}
